import math
from fractions import Fraction

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def dot(u, v):
    return sum(u[i] * v[i] for i in range(len(u)))

def project(basis, x):
    for i in range(len(basis)):
        for j in range(i + 1, len(basis)):
            if dot(basis[i], basis[j]) != 0:
                print("  basis not orthogonal")
                return
    p = [Fraction(0)] * len(x)
    for u in basis:
        c = Fraction(dot(x, u), dot(u, u))
        p = [p[i] + c * u[i] for i in range(len(x))]
    e = [x[i] - p[i] for i in range(len(x))]
    print(f"  p = {vec(p)}")
    print(f"  e = {vec(e)}")
    print(f"  e . u = 0 for every u: {all(dot(e, u) == 0 for u in basis)}")
    print(f"  distance {math.sqrt(dot(e, e)):.4f}")

k = int(input())
for t in range(k):
    n = int(input())
    basis = [[Fraction(w) for w in input().split()] for i in range(n)]
    x = [Fraction(w) for w in input().split()]
    print(f"x = {vec(x)} onto W = span of {', '.join(vec(u) for u in basis)}")
    project(basis, x)

