import math
from fractions import Fraction

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def dot(u, v):
    return sum(u[i] * v[i] for i in range(len(u)))

def clear(v):
    lcm = 1
    for w in v:
        lcm = math.lcm(lcm, w.denominator)
    whole = [int(w * lcm) for w in v]
    g = 0
    for w in whole:
        g = math.gcd(g, w)
    return [Fraction(w, g) for w in whole]

def gram_schmidt(xs):
    vs = []
    for j in range(len(xs)):
        v = xs[j]
        for u in vs:
            c = dot(xs[j], u) / dot(u, u)
            v = [v[i] - c * u[i] for i in range(len(v))]
        if all(w == 0 for w in v):
            print(f"  x{j + 1} dropped")
        else:
            vs.append(clear(v))
            print(f"  v{len(vs)} = {vec(vs[-1])}")
    ok = all(dot(vs[i], vs[j]) == 0 for i in range(len(vs)) for j in range(i + 1, len(vs)))
    print(f"  all pairs orthogonal: {ok}")

k = int(input())
for t in range(k):
    n = int(input())
    xs = [[Fraction(w) for w in input().split()] for i in range(n)]
    print(", ".join(vec(x) for x in xs))
    gram_schmidt(xs)

