from fractions import Fraction

def show(M):
    return "  ".join("[" + ", ".join(str(x) for x in row) + "]" for row in M)

def det(Q):
    if len(Q) == 2:
        return Q[0][0] * Q[1][1] - Q[0][1] * Q[1][0]
    return sum((-1) ** j * Q[0][j] * det([row[:j] + row[j + 1:] for row in Q[1:]]) for j in range(len(Q)))

def classify(Q):
    n = len(Q)
    QtQ = [[sum(Q[k][i] * Q[k][j] for k in range(n)) for j in range(n)] for i in range(n)]
    if QtQ != [[1 if i == j else 0 for j in range(n)] for i in range(n)]:
        print(f"  not orthogonal: Q^T Q = {show(QtQ)}")
        return
    d = det(Q)
    print(f"  orthogonal, det {d}")
    print("  rotation" if d == 1 else "  reflection")

k = int(input())
for t in range(k):
    n = int(input())
    Q = [[Fraction(w) for w in input().split()] for i in range(n)]
    print(f"Q = {show(Q)}")
    classify(Q)
